PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS parties (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS warehouses (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, is_sales_default INTEGER NOT NULL DEFAULT 0 CHECK (is_sales_default IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, name TEXT NOT NULL, sku TEXT NOT NULL UNIQUE, barcode TEXT, piece_cost INTEGER NOT NULL CHECK (piece_cost >= 0), piece_price INTEGER, carton_price INTEGER, pieces_per_carton INTEGER NOT NULL DEFAULT 1 CHECK (pieces_per_carton > 0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, number TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK (kind IN ('purchase','sale','return','transfer','adjustment','expense','payment','offset','settlement')), party_id TEXT REFERENCES parties(id), warehouse_id TEXT REFERENCES warehouses(id), destination_warehouse_id TEXT REFERENCES warehouses(id), parent_document_id TEXT REFERENCES documents(id), payment_method TEXT, status TEXT NOT NULL DEFAULT 'posted', title TEXT, total INTEGER NOT NULL DEFAULT 0 CHECK (total >= 0), due_total INTEGER NOT NULL DEFAULT 0 CHECK (due_total >= 0), recurrence_key TEXT UNIQUE, occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS document_lines (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), product_id TEXT REFERENCES products(id), description TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1 CHECK (quantity >= 0), unit_price INTEGER NOT NULL DEFAULT 0 CHECK (unit_price >= 0), line_total INTEGER NOT NULL DEFAULT 0 CHECK (line_total >= 0));
CREATE TABLE IF NOT EXISTS stock_balances (warehouse_id TEXT NOT NULL REFERENCES warehouses(id), product_id TEXT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL DEFAULT 0 CHECK (quantity >= 0), PRIMARY KEY (warehouse_id, product_id));
CREATE TABLE IF NOT EXISTS stock_movements (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), warehouse_id TEXT NOT NULL REFERENCES warehouses(id), product_id TEXT NOT NULL REFERENCES products(id), movement_type TEXT NOT NULL CHECK (movement_type IN ('purchase','sale','transfer-in','transfer-out','return','adjustment')), quantity_delta INTEGER NOT NULL, balance_before INTEGER NOT NULL, balance_after INTEGER NOT NULL CHECK (balance_after >= 0), occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ledger_entries (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), party_id TEXT NOT NULL REFERENCES parties(id), side TEXT NOT NULL CHECK (side IN ('receivable','payable')), amount_delta INTEGER NOT NULL, occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS allocations (id TEXT PRIMARY KEY, settlement_document_id TEXT NOT NULL REFERENCES documents(id), source_document_id TEXT NOT NULL REFERENCES documents(id), side TEXT NOT NULL CHECK (side IN ('receivable','payable')), amount INTEGER NOT NULL CHECK (amount > 0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (settlement_document_id, source_document_id, side));
CREATE TABLE IF NOT EXISTS recurring_expenses (id TEXT PRIMARY KEY, title TEXT NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0), frequency TEXT NOT NULL CHECK (frequency IN ('daily','monthly')), starts_on TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, document_id TEXT REFERENCES documents(id), action TEXT NOT NULL, payload TEXT NOT NULL DEFAULT '{}', user_name TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_documents_party ON documents(party_id, occurred_at);
CREATE INDEX IF NOT EXISTS idx_documents_warehouse ON documents(warehouse_id, occurred_at);
CREATE INDEX IF NOT EXISTS idx_lines_document ON document_lines(document_id);
CREATE INDEX IF NOT EXISTS idx_movements_product ON stock_movements(warehouse_id, product_id, occurred_at);
CREATE INDEX IF NOT EXISTS idx_ledger_party ON ledger_entries(party_id, occurred_at);
CREATE INDEX IF NOT EXISTS idx_allocations_source ON allocations(source_document_id, side);
CREATE TRIGGER IF NOT EXISTS immutable_posted_documents BEFORE DELETE ON documents WHEN OLD.status = 'posted' BEGIN SELECT RAISE(ABORT, 'posted documents are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_stock_movements BEFORE DELETE ON stock_movements BEGIN SELECT RAISE(ABORT, 'stock movements are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_ledger_entries BEFORE DELETE ON ledger_entries BEGIN SELECT RAISE(ABORT, 'ledger entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS allocation_not_over_source BEFORE INSERT ON allocations BEGIN SELECT CASE WHEN (SELECT COALESCE(SUM(amount),0) FROM allocations WHERE source_document_id = NEW.source_document_id AND side = NEW.side) + NEW.amount > (SELECT due_total FROM documents WHERE id = NEW.source_document_id) THEN RAISE(ABORT, 'allocation exceeds source due') END; END;
